<?php

namespace App\Notifications;

use App\Models\RentAgreement;
use Illuminate\Bus\Queueable;
use Illuminate\Notifications\Messages\MailMessage;
use Illuminate\Notifications\Notification;

/**
 * Sent to both the landlord and the tenant when a rent agreement is
 * generated by the municipality.
 *
 * Previously an agreement was created silently — the only way for either
 * party to learn about it was to go looking on the "Rent Agreements"
 * page. This notification is the distribution half of the requirement.
 */
class RentAgreementGenerated extends Notification
{
    use Queueable;

    public function __construct(private readonly RentAgreement $agreement) {}

    public function via(object $notifiable): array
    {
        return ['mail'];
    }

    public function toMail(object $notifiable): MailMessage
    {
        $message = (new MailMessage)
            ->subject('Rent Agreement '.$this->agreement->agreement_number.' — '.$this->agreement->property?->title)
            ->line('A rent agreement has been issued for '.($this->agreement->property?->title ?? 'your property').'.')
            ->line('Agreement number: '.$this->agreement->agreement_number)
            ->line('Monthly rent: BDT '.number_format((float) $this->agreement->monthly_rent, 2))
            ->line('Security deposit: BDT '.number_format((float) $this->agreement->security_deposit, 2))
            ->line('Term: '.$this->agreement->start_date?->format('M d, Y').' to '.$this->agreement->end_date?->format('M d, Y'));

        /*
         * Point the recipient at the agreement in the portal. The URL is
         * absolute because mail clients do not resolve relative paths.
         */
        if ($notifiable->id === $this->agreement->tenant_id) {
            $message->line('You are the tenant of this agreement.')
                ->action('View agreement', url(route('citizen.rent-agreements.show', $this->agreement)));
        } else {
            $message->line('You are the landlord of this agreement.')
                ->action('View agreement', url(route('citizen.rent-agreements.show', $this->agreement)));
        }

        return $message->line('Thank you for using the citizen services portal.');
    }

    public function toArray(object $notifiable): array
    {
        return [
            'rent_agreement_id' => $this->agreement->id,
            'agreement_number' => $this->agreement->agreement_number,
            'property_id' => $this->agreement->property_id,
        ];
    }
}
